(* [comment removed for export] *)
Definition sro_at_call (C : rsc) (MA MR : Z) (sp : word) (fr : list cell) (w : rsw) (cf : config) : Prop :=
  exists (t0 t1 t2 a4 a5 a6 a7 s5x t3 t4 t5 t6 : word) (m : mem) (s : as_St H) (errv : word) (E : ecv) (XS : list (Z * Z)),
    as_VIS H s (cfg_ms cf) = sro_call_ms sp (c_P C) (c_E C) (c_bs C) (c_fb C) (c_gp C) (c_tp C) t0 t1 t2 a4 a5 a6 a7 s5x t3 t4 t5 t6 (c_F C) (c_fc C) m
    /\ pc_state (ps_c (w_d w)) <> 11
    /\ as_AKREL H s cf /\ as_MPRES H (c_mo0 C) (cfg_model cf)
    /\ RWm H C w s errv E m /\ RWp H C MA w /\ al_ok H s (ps_A (w_d w)) MA MR
    /\ stk asegs m (c_lo C) (bv_unsigned sp + -128) /\ rw_cells asegs m (bv_unsigned sp + -128) fr
    /\ Forall (fs_scratch H (c_LF C)) XS
    /\ xpres H (c_LBin C) (c_SP C) (hread_X (c_P C) (c_E C) (c_fb C) (c_stb C) [] [] ++ XS) (c_m0 C) m
