Definition sro_ret (C : rsc) (MA MR : Z) (sp rae s0e s1e s2e s3e s4e s5e s6e s7e s8e s9e s10e s11e : word) (cf : config) : Prop :=
  exists (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m : mem) (w : rsw) (s : as_St H) (errv : word) (E : ecv) (XS : list (Z * Z)),
    as_VIS H s (cfg_ms cf) = MS (mkR rae sp (c_gp C) (c_tp C) t0 t1 t2 s0e s1e a0 a1 a2 a3 a4 a5 a6 a7 s2e s3e s4e s5e s6e s7e s8e s9e s10e s11e t3 t4 t5 t6)
                              (c_F C) (ret_pc rae) (c_fc C) None m (seg_rom asegs)
    /\ as_AKREL H s cf /\ as_MPRES H (c_mo0 C) (cfg_model cf)
    /\ RWm H C w s errv E m /\ RWp H C MA w /\ al_ok H s (ps_A (w_d w)) MA MR
    /\ stk asegs m (c_lo C) (bv_unsigned sp)
